package mypackage5ap;

public class Patterns5b {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		for(int p=0;p<=5;p++) {
			for(int q=p;q<=5;q++) {
				System.out.print(" ");
			}
			for(int r=p;r>=0;r--) {
				System.out.print("*");
			}
			System.out.println();
		}


	}

}
